video_cover = #{videoInfo.videoCover}, video_name = #{videoInfo.videoName}, user_id = #{videoInfo.userId}, last_update_time = #{videoInfo.lastUpdateTime}, p_category_id = #{videoInfo.pCategoryId}, category_id = #{videoInfo.categoryId}, post_type = #{videoInfo.postType}, origin_info = #{videoInfo.originInfo}, tags = #{videoInfo.tags}, introduction = #{videoInfo.introduction}, interaction = #{videoInfo.interaction}, duration = #{videoInfo.duration}, play_count = #{videoInfo.playCount}, like_count = #{videoInfo.likeCount}, danmu_count = #{videoInfo.danmuCount}, comment_count = #{videoInfo.commentCount}, coin_count = #{videoInfo.coinCount}, collect_count = #{videoInfo.collectCount}, recommend_type = #{videoInfo.recommendType}, last_play_time = #{videoInfo.lastPlayTime},
WHERE video_id = #{videoId}

update video_info set ${field} = ${field} + #{changeCount}

    , last_play_time = now()

